import React from 'react';
import { questions } from '../data/questions';

const Summary = ({ answers, onRestart }) => {
  // Calculate total cost
  const totalCost = Object.values(answers).reduce((sum, answer) => sum + (answer?.cost || 0), 0);

  // Personality archetype analysis
  const analyzePersonality = () => {
    const archetypeScores = {
      peacefulSoul: 0,
      lifeCelebrator: 0,
      legacyGiver: 0,
      heartGuardian: 0,
      quietPhilosopher: 0
    };

    // Keywords for each archetype
    const archetypeKeywords = {
      peacefulSoul: ['สงบ', 'ธรรมชาติ', 'เงียบ', 'เรียบง่าย', 'จุดจบ', 'พิธีเงียบ'],
      lifeCelebrator: ['สนุก', 'ร่าเริง', 'ปาร์ตี้', 'เฉลิมฉลอง', 'เพลงสนุก', 'กลางคืน'],
      legacyGiver: ['แรงบันดาลใจ', 'ความทรงจำ', 'จดจำ', 'มอบสิ่งของ', 'พัฒนาตัวเอง'],
      heartGuardian: ['ปลอบใจ', 'อบอุ่น', 'ครอบครัว', 'น้ำตา', 'คำพูดซึ้ง', 'รัก'],
      quietPhilosopher: ['เรียบง่าย', 'ศาสนา', 'ลึกซึ้ง', 'จุดเริ่มต้น', 'เขียนจดหมาย']
    };

    // Analyze each answer
    Object.entries(answers).forEach(([questionId, answer]) => {
      if (!answer?.text) return;

      const answerText = answer.text.toLowerCase();
      
      // Check which archetype keywords appear in the answer
      Object.entries(archetypeKeywords).forEach(([archetype, keywords]) => {
        keywords.forEach(keyword => {
          if (answerText.includes(keyword.toLowerCase())) {
            archetypeScores[archetype]++;
          }
        });
      });
    });

    // Find top archetypes
    const sortedArchetypes = Object.entries(archetypeScores)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 2);

    return {
      primaryType: sortedArchetypes[0][0],
      secondaryType: sortedArchetypes[1][0],
      scores: archetypeScores
    };
  };

  // Generate personalized summary
  const generateSummary = (personality) => {
    const archetypeSummaries = {
      peacefulSoul: {
        title: "ผู้แสวงหาความสงบ",
        description: "ชีวิตของคุณคือการเดินทางอย่างสงบ คุณต้องการให้งานศพเรียบง่าย เงียบสงบ และเต็มไปด้วยความรักอ่อนโยน"
      },
      lifeCelebrator: {
        title: "ผู้เฉลิมฉลองชีวิต",
        description: "คุณคือคนที่ใช้ชีวิตอย่างเต็มที่ แม้ในวันสุดท้ายคุณก็ยังอยากให้ทุกคนเฉลิมฉลองในแบบของคุณ"
      },
      legacyGiver: {
        title: "ผู้สร้างมรดก",
        description: "คุณเชื่อว่าชีวิตคือการสร้างผลกระทบให้ผู้อื่น คุณอยากให้คนจำคุณในแง่ดีและเรียนรู้จากสิ่งที่คุณทิ้งไว้"
      },
      heartGuardian: {
        title: "ผู้พิทักษ์หัวใจ",
        description: "คุณเป็นคนที่ใส่ใจผู้อื่นลึกซึ้ง ในวันสุดท้ายคุณต้องการให้ทุกคนรู้ว่าความรักยังคงอยู่แม้จากลา"
      },
      quietPhilosopher: {
        title: "นักคิดเงียบ",
        description: "คุณมองความตายอย่างมีความหมาย ไม่ใช่เพียงการจากไปแต่เป็นการส่งต่อความคิดและความรักเงียบ ๆ"
      }
    };

    const primary = archetypeSummaries[personality.primaryType];
    const secondary = archetypeSummaries[personality.secondaryType];

    return {
      title: primary.title,
      description: `${primary.description} ${secondary ? `และ${secondary.description}` : ''}`
    };
  };

  // Get funeral details
  const getFuneralDetails = () => {
    const reflectionAnswers = questions
      .filter(q => q.section === 'reflection')
      .map(q => ({ question: q.question, answer: answers[q.id]?.text || 'ไม่ระบุ' }));

    const practicalAnswers = questions
      .filter(q => q.section === 'practical')
      .map(q => ({ question: q.question, answer: answers[q.id]?.text || 'ไม่ระบุ', cost: answers[q.id]?.cost || 0 }));

    // Determine style based on reflection answers
    const styleCounts = {
      traditional: 0,
      modern: 0,
      minimal: 0,
      luxury: 0
    };

    Object.values(answers).forEach(answer => {
      if (answer?.tags) {
        answer.tags.forEach(tag => {
          if (styleCounts.hasOwnProperty(tag)) {
            styleCounts[tag]++;
          }
        });
      }
    });

    const dominantStyle = Object.entries(styleCounts).reduce((a, b) => a[1] > b[1] ? a : b)[0];
    const styleName = {
      traditional: 'แบบดั้งเดิม',
      modern: 'แบบสมัยใหม่',
      minimal: 'แบบเรียบง่าย',
      luxury: 'แบบหรูหรา'
    }[dominantStyle];

    return {
      style: styleName,
      reflection: reflectionAnswers,
      practical: practicalAnswers,
      totalCost
    };
  };

  const details = getFuneralDetails();
  const personality = analyzePersonality();
  const summary = generateSummary(personality);

  // Calculate break-even points
  const breakEvenPoints = {
    '500': Math.ceil(details.totalCost / 500),
    '1000': Math.ceil(details.totalCost / 1000),
    '2000': Math.ceil(details.totalCost / 2000)
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: 'แผนงานศพของฉัน',
        text: `สไตล์: ${details.style}\nบุคลิก: ${summary.title}\nงบประมาณ: ${details.totalCost.toLocaleString()} บาท\nจุดคุ้มทุน: ${breakEvenPoints['500']} คน (500 บาท/คน)`,
        url: window.location.href
      });
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-900 to-black text-white p-6 animate-fade-in">
      <div className="max-w-4xl mx-auto space-y-8">
        {/* Header */}
        <div className="text-center space-y-4 animate-slide-up">
          <div className="relative">
            <h1 className="text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-red-500 to-pink-500">
              📋 สรุปแผนงานศพของคุณ
            </h1>
            <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-32 h-1 bg-gradient-to-r from-red-500 to-pink-500 rounded-full"></div>
          </div>
          <p className="text-2xl text-gray-300 mt-4">💎 สไตล์: {details.style}</p>
          <p className="text-2xl text-gray-300">🌟 บุคลิก: {summary.title}</p>
        </div>

        {/* Personality Summary */}
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.1s' }}>
          <h2 className="text-3xl font-bold text-red-400 mb-6">✨ บทสรุปบุคลิกของคุณ</h2>
          <p className="text-xl text-gray-300 leading-relaxed">{summary.description}</p>
        </div>

        {/* Reflection Summary */}
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.2s' }}>
          <h2 className="text-3xl font-bold text-red-400 mb-6">🔹 คำตอบจากส่วนสำรวจความรู้สึกภายใน</h2>
          <div className="space-y-4">
            {details.reflection.map((item, index) => (
              <div key={index} className="border-b border-gray-700 pb-4">
                <h3 className="text-lg font-semibold text-gray-300 mb-2">{item.question}</h3>
                <p className="text-white">{item.answer}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Practical Details */}
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.4s' }}>
          <h2 className="text-3xl font-bold text-red-400 mb-6">🔹 รายละเอียดการจัดงาน</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {details.practical.map((item, index) => (
              <div key={index} className="bg-gray-700/50 rounded-xl p-4">
                <h3 className="text-lg font-semibold text-gray-300 mb-2">{item.question}</h3>
                <p className="text-white mb-2">{item.answer}</p>
                {item.cost > 0 && (
                  <p className="text-red-400">ค่าใช้จ่าย: {item.cost.toLocaleString()} บาท</p>
                )}
              </div>
            ))}
          </div>
        </div>

        {/* Cost Analysis */}
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.6s' }}>
          <h2 className="text-3xl font-bold text-red-400 mb-6">💰 การวิเคราะห์ค่าใช้จ่าย</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="text-center p-6 bg-gray-700/50 rounded-xl">
              <h3 className="text-xl font-semibold text-gray-300 mb-2">งบโดยรวม</h3>
              <p className="text-4xl font-bold text-white">{details.totalCost.toLocaleString()} บาท</p>
            </div>
            <div className="text-center p-6 bg-gray-700/50 rounded-xl">
              <h3 className="text-xl font-semibold text-gray-300 mb-2">จุดคุ้มทุน</h3>
              <div className="space-y-2">
                <p className="text-lg text-white">{breakEvenPoints['500']} คน (500 บาท/คน)</p>
                <p className="text-lg text-white">{breakEvenPoints['1000']} คน (1,000 บาท/คน)</p>
                <p className="text-lg text-white">{breakEvenPoints['2000']} คน (2,000 บาท/คน)</p>
              </div>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex justify-center space-x-4 animate-fade-in-delay">
          <button
            onClick={onRestart}
            className="px-8 py-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors duration-300"
          >
            เริ่มต้นใหม่
          </button>
          <button
            onClick={handleShare}
            className="px-8 py-3 bg-gray-700 text-white rounded-xl hover:bg-gray-600 transition-colors duration-300"
          >
            แชร์ผลลัพธ์
          </button>
        </div>

        {/* Footer with Quote */}
        <div className="text-center space-y-4 animate-fade-in-delay">
          <div className="relative">
            <p className="text-2xl italic text-gray-300">
              "งานศพของคุณจะเป็นงานที่สวยงาม หรูหรา และเต็มไปด้วยความรักและความทรงจำดี ๆ"
            </p>
            <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-16 h-0.5 bg-red-500 rounded-full"></div>
          </div>
          <p className="text-sm text-gray-500">#วางแผนงานศพ #เตรียมตัวก่อนตาย</p>
        </div>
      </div>
    </div>
  );
};

export default Summary;
